#!/usr/bin/env python3
from pathlib import Path
import csv
from openpyxl import Workbook
from openpyxl.styles import Font,PatternFill,Alignment
from openpyxl.cell.cell import ILLEGAL_CHARACTERS_RE
ROOT=Path(__file__).resolve().parents[1]
def count(name):
 with (ROOT/name).open(encoding='utf-8') as f:return sum(1 for _ in csv.DictReader(f))
w=Workbook();s=w.active;s.title='Read me'
for row in [ ['Paper 1 source-driven evidence workbook'],['Current draft', 'manuscript/Paper_1_draft.md and .docx'],['Coverage','93 PDFs / 92 unique publications; all92 targeted full-text (48 initial +44 follow-up); extraction is selective.'],['Follow-up review', '44 manual cards;140 located values;18 accepted within-source/utility-reference quantities.'],['Mixed benchmark', '12 annual MILPs;72 operating reevaluations;18 dispatch controls. No calibrated regional optimum/full LCA.'],['Density check','Pure-CO2 EOS reference supports table consistency; actual mixture/datum not validated.'],['New reference intake','104 uploads;100 archived;4 exceed32MiB; indexed is not fully reviewed.'],['Reference inventory','8 NETL cases;20 utility scenarios;2,980 partial inventory comparisons.'],['Reference located inputs',count('data/reference_inventory_inputs.csv')],['IBDP simulation quantities',count('data/ibdp_reservoir_reference_values.csv')],['Native workbook archive','17 workbooks;1,013,036 nonempty/formula cells in evidence/reference_workbooks; raw cells are not validated independent observations.'],['Extraction records',count('data/all_extracted_values.csv')],['Curated PDF records',count('data/curated_values.csv')],['Supplement numeric records',count('data/supplement_values.csv')],['Original benchmark input rows',134],['Supplement annual grid','720 cells; 250 printed values and 470 blanks; rounded allocation replay'],['Operational inputs',count('data/operational_parameters.csv')],['Operational comparisons','144 comparisons,36 contrasts; partial active fuel boundary, not complete LCA'],['Outputs','49 calculations plus 75 directly transcribed fleet outputs.'],['Scientific scope','Primary controlled/mixed results have partial inventories. Cross-study score is AppendixA supporting diagnostic; complete net avoided GHG is uncomputed.'],['Status','HOLD records are excluded from analysis. Broad extraction records are not harmonised regional inputs.'],['Reproduce','python paper1/scripts/reproduce.py; python -m unittest discover -s paper1/tests -v'],['Metadata','Read data dictionary, proxy register and evidence digest for full limits.'] ]:s.append(row)
files=[('Source catalogue','data/source_catalogue.csv'),('All extracted values','data/all_extracted_values.csv'),('Curated values','data/curated_values.csv'),('Analysis inputs','data/analysis_inputs.csv'),('New paper values','data/new_batch_values.csv'),('Calculated results','outputs/calculated_results.csv'),('Source issues','data/issues.csv'),('Proposal audit','data/proposal_claim_audit.csv'),('Supplement documents','data/supplement_documents.csv'),('Supplement values','data/supplement_values.csv'),('Supplement sources','data/supplement_sources.csv'),('Supplement reservoirs','data/supplement_reservoirs.csv'),('Supplement distances','data/supplement_distances.csv'),('Annual allocation grid','data/supplement_annual_injection.csv'),('Annual replay','outputs/supplement_annual_replay.csv'),('Replay summary','outputs/supplement_scenario_summary.csv'),('Operating inputs','data/operational_parameters.csv'),('Operating comparisons','outputs/operational_comparisons.csv'),('Operating contrasts','outputs/operational_contrasts.csv'),('Operating controls','outputs/operational_controls.csv'),('Fleet adequacy','outputs/operational_design_adequacy.csv'),('Selected fleet comparison','outputs/operational_design_comparisons.csv'),('Operating data gaps','data/operational_data_gaps.csv'),('Reference catalogue','data/reference_dataset_catalogue.csv'),('Reference input values','data/reference_inventory_inputs.csv'),('NETL capture references','data/netl_capture_reference_cases.csv'),('Utility scenarios','data/capture_utility_scenarios.csv'),('Reference inventory balances','outputs/reference_inventory_comparisons.csv'),('Japan current factors','data/japan_current_factors.csv'),('Wave coverage','data/wave_coverage.csv'),('Wave snapshot values','data/wave_snapshot_values.csv'),('IBDP simulation values','data/ibdp_reservoir_reference_values.csv'),('IBDP checksum audit','data/ibdp_bag_checksum_audit.csv'),('Japanese case catalogue','data/dataset7_catalogue.csv'),('Japanese case values','data/case_numeric_values.csv'),('Japan company history','data/japan_company_emissions.csv'),('Japan facility candidates','data/japan_facility_candidates.csv'),('CPPI annex','data/cppi_port_reference.csv'),('Tomakomai monthly','data/tomakomai_monthly_history.csv'),('Tomakomai fiscal','data/tomakomai_fiscal_history.csv'),('Tomakomai shut-in tests','data/tomakomai_shutin_tests.csv'),('Tomakomai fall-off','data/tomakomai_falloff_reference.csv'),('Tomakomai completions','data/tomakomai_completion_scenarios.csv'),('Tomakomai history audit','outputs/tomakomai_history_audit.csv'),('NL component values','data/northern_lights_components.csv'),('Case-derived checks','outputs/case_evidence_calculations.csv'),('NL storage sensitivity','outputs/northern_lights_storage_proxy_comparisons.csv')]
files += [('Follow-up review values','data/deep_review_values.csv'),('Follow-up accepted inputs','data/limitation_benchmark_inputs.csv'),('Within-source checks','outputs/limitation_benchmark_results.csv'),('MEA reference utility','data/deep_capture_reference_case.csv'),('MEA reference margins','outputs/MEA_reference_comparisons.csv'),('Density source inputs','data/property_check_inputs.csv'),('EOS density checks','outputs/property_consistency.csv'),('EOS fleet sensitivity','outputs/property_fleet_sensitivity.csv'),('Mixed reservoir plans','outputs/mixed_reservoir_plans.csv'),('Mixed voyage plans','outputs/mixed_trip_plans.csv'),('Mixed annual solves','outputs/mixed_solver_audit.csv'),('Mixed operating comparisons','outputs/mixed_operational_comparisons.csv'),('Mixed annual operation','outputs/mixed_operational_annual.csv'),('Dispatch controls','outputs/dispatch_policy_controls.csv')]
assert len({x[0] for x in files})==len(files) and all(len(x[0])<=31 for x in files)
for title,p in files:
 s=w.create_sheet(title)
 with (ROOT/p).open(encoding='utf-8') as f:
  for row in csv.reader(f):
   # PDF font control codes can be retained in UTF-8 evidence but are illegal XML.
   # Remove them from this display copy only; the CSV and source stay authoritative.
   cells=[ILLEGAL_CHARACTERS_RE.sub('',x) for x in row]
   s.append(["'"+x if x.startswith('=') else x for x in cells])
 s.freeze_panes='A2';s.auto_filter.ref=s.dimensions
for s in w:
 for cell in s[1]:cell.font=Font(bold=True,color='FFFFFF');cell.fill=PatternFill('solid',fgColor='24475B')
 for row in s.iter_rows(min_row=2):
  for cell in row:cell.alignment=Alignment(wrap_text=True,vertical='top')
 for col in s.columns:
  length=max(len(str(c.value or '')) for c in list(col)[:30]);s.column_dimensions[col[0].column_letter].width=min(55,max(15,length*.7))
w.save(ROOT/'data/Paper_1_evidence.xlsx');print('Saved evidence workbook')
